entries[39674] = { ["name"] = "Verbannen", ["text"] = "100 Mana 30 Meter Reichweite\nWirken in 1 sek.\nVerbannt einen Feind und verhindert damit jegliche Aktion, macht es aber bis zu 15 Sek. lang unverwundbar. Es kann immer nur jeweils ein Ziel verbannt werden." }
entries[39675] = { ["name"] = "Manabrand", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nTrifft einen Feind mit einem Antimanablitz. Für jeden vom Blitz verbrauchten Manapunkt erleidet das Ziel 0.5 Schaden." }
