entries[39685] = { ["name"] = "Mine legen", ["text"] = "30 Mana 50 Meter Reichweite\nSofort 10 sek. Abklingzeit\nPlatziert eine Landmine. Die Mine ist nach 3 Sek. scharf und verursacht, wenn sie ausgelöst wird, bei allen Panzern in einem Radius von 2 Metern 40 Schaden." }
