entries[39692] = { ["name"] = "Kanone", ["text"] = "15 Meter Reichweite\nSofort 4 sek. Abklingzeit\nFeuert eine Kanonenkugel auf den nächstgelegenen Panzer ab, der sich bis zu 20 Meter vor Euch befindet. Verursacht 13 Schaden." }
entries[39693] = { ["name"] = "Flammenwerfer", ["text"] = "15 Meter Reichweite\nSofort 2 sek. Abklingzeit\nVerbraucht 10 Mana pro Sekunde.\nVerursacht alle 1 Sek. 2000 Schaden bei allen Panzern, die sich bis zu 5 Meter vor Euch befinden. Die Bewegungsgeschwindigkeit der betroffenen Ziele wird auf 20% des normalen Tempos verringert und ihnen wird pro Sekunde 500 Schaden zugefügt. Hält 2 Sek. lang an." }
entries[39694] = { ["name"] = "MG-Turm aktivieren", ["text"] = "Sofort 10 sek. Abklingzeit\nVerbraucht 10 Mana pro Sekunde.\nSchießt automatisch alle 1 Sek. auf den nächsten Feind in einem Umkreis von 10 Metern und verursacht mit jedem Schuss 3 Schaden." }
entries[39695] = { ["name"] = "Mörser", ["text"] = "30 Meter Reichweite\nSofort 5 sek. Abklingzeit\nFeuert ein Mörsergeschoss ab, welches 25 Meter entfernt einschlägt und bei allen Panzern in einem Umkreis von 5 Metern 26 Schaden verursacht." }
