entries[39798] = { ["name"] = "Grüner Reitnetherrochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren grünen Netherrochen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n\"Netherrochen gehören zu den zuverlässigsten und vielseitigsten Reittieren der Scherbenwelt und auch darüber hinaus.\"\nVerkäufer:\nGrella\nZone:\nWälder von Terokkar, Scherbenwelt\nHimmelswache der Sha'tari - Ehrfürchtig\nKosten:\n200" }
